import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.C0KMm31j.js";const o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_26_dagger_overview.png",l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_26_state_coverage.png",h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_26_dagger_loop.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_26_expert_labels.png",s="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_26_driving_dagger_boundary.png",m=JSON.parse('{"title":"专家只看训练集不够：DAgger 如何修复行为克隆的分布偏移","description":"行为克隆最根本的缺陷是训练数据来自专家策略，部署状态却由学习策略自己产生。策略在训练集没见过的状态上犯一次小错，下一状态就更偏离专家分布，错误可能像滚雪球一样扩大。DAgger（Dataset Aggregation，数据集聚合）直接改变数据采集方式：让当前学习策略访问自己的状态，再由专家为这些状态","frontmatter":{"title":"专家只看训练集不够：DAgger 如何修复行为克隆的分布偏移","description":"行为克隆最根本的缺陷是训练数据来自专家策略，部署状态却由学习策略自己产生。策略在训练集没见过的状态上犯一次小错，下一状态就更偏离专家分布，错误可能像滚雪球一样扩大。DAgger（Dataset Aggregation，数据集聚合）直接改变数据采集方式：让当前学习策略访问自己的状态，再由专家为这些状态","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":7,"source":"2026-08-13/rl_series_26_dagger_dataset_aggregation.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_26_dagger_overview.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-26-dagger-dataset-aggregation"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"专家只看训练集不够：DAgger 如何修复行为克隆的分布偏移"}],["meta",{"property":"og:description","content":"行为克隆最根本的缺陷是训练数据来自专家策略，部署状态却由学习策略自己产生。策略在训练集没见过的状态上犯一次小错，下一状态就更偏离专家分布，错误可能像滚雪球一样扩大。DAgger（Dataset Aggregation，数据集聚合）直接改变数据采集方式：让当前学习策略访问自己的状态，再由专家为这些状态"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-26-dagger-dataset-aggregation"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_26_dagger_overview.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"专家只看训练集不够：DAgger 如何修复行为克隆的分布偏移"}],["meta",{"name":"twitter:description","content":"行为克隆最根本的缺陷是训练数据来自专家策略，部署状态却由学习策略自己产生。策略在训练集没见过的状态上犯一次小错，下一状态就更偏离专家分布，错误可能像滚雪球一样扩大。DAgger（Dataset Aggregation，数据集聚合）直接改变数据采集方式：让当前学习策略访问自己的状态，再由专家为这些状态"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_26_dagger_overview.png"}]],"prev":{"text":"不知道奖励怎么写？先用行为克隆学会专家怎么做","link":"/rl/rl-series-25-behavior-cloning"},"next":{"text":"专家到底在追求什么？从逆强化学习到 GAIL","link":"/rl/rl-series-27-irl-gail"}},"headers":[],"relativePath":"rl/rl-series-26-dagger-dataset-aggregation.md","filePath":"rl/rl-series-26-dagger-dataset-aggregation.md","lastUpdated":null}'),g={name:"rl/rl-series-26-dagger-dataset-aggregation.md"};function d(c,a,p,_,u,b){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="专家只看训练集不够-dagger-如何修复行为克隆的分布偏移" tabindex="-1">专家只看训练集不够：DAgger 如何修复行为克隆的分布偏移 <a class="header-anchor" href="#专家只看训练集不够-dagger-如何修复行为克隆的分布偏移" aria-label="Permalink to &quot;专家只看训练集不够：DAgger 如何修复行为克隆的分布偏移&quot;">​</a></h1><p>行为克隆最根本的缺陷是训练数据来自专家策略，部署状态却由学习策略自己产生。策略在训练集没见过的状态上犯一次小错，下一状态就更偏离专家分布，错误可能像滚雪球一样扩大。DAgger（Dataset Aggregation，数据集聚合）直接改变数据采集方式：让当前学习策略访问自己的状态，再由专家为这些状态提供动作标签，反复把新数据加入训练集。</p><p>DAgger 不是“多收集一些专家正常驾驶数据”，而是让专家覆盖学习策略实际会走到的分布。它仍需要专家在线查询、混合策略、标签延迟处理和安全干预设计。若专家只能在危险状态被动接管，数据采集成本和风险会很高；若混合比例退火过快，策略仍可能过早脱离可恢复区域。</p><h2 id="一、先给出整篇文章的结论" tabindex="-1">一、先给出整篇文章的结论 <a class="header-anchor" href="#一、先给出整篇文章的结论" aria-label="Permalink to &quot;一、先给出整篇文章的结论&quot;">​</a></h2><h3 id="_1-1-dagger-让数据分布接近学习策略" tabindex="-1">1.1 DAgger 让数据分布接近学习策略 <a class="header-anchor" href="#_1-1-dagger-让数据分布接近学习策略" aria-label="Permalink to &quot;1.1 DAgger 让数据分布接近学习策略&quot;">​</a></h3><p>当前策略参与执行，专家只负责对访问状态给出正确动作。数据集逐轮聚合，训练目标与部署分布更一致。</p><h3 id="_1-2-混合策略是安全过渡机制" tabindex="-1">1.2 混合策略是安全过渡机制 <a class="header-anchor" href="#_1-2-混合策略是安全过渡机制" aria-label="Permalink to &quot;1.2 混合策略是安全过渡机制&quot;">​</a></h3><p>早期由专家更多接管，后期逐步增加学习策略执行比例。混合不是形式要求，而是避免学习策略直接进入不可恢复状态。</p><h3 id="_1-3-dagger-依赖可查询专家" tabindex="-1">1.3 DAgger 依赖可查询专家 <a class="header-anchor" href="#_1-3-dagger-依赖可查询专家" aria-label="Permalink to &quot;1.3 DAgger 依赖可查询专家&quot;">​</a></h3><p>专家需要能在学习策略访问的状态上给出动作或代价。昂贵、延迟或不确定的专家会成为瓶颈。</p><h3 id="_1-4-理论保证不等于真实车辆许可" tabindex="-1">1.4 理论保证不等于真实车辆许可 <a class="header-anchor" href="#_1-4-理论保证不等于真实车辆许可" aria-label="Permalink to &quot;1.4 理论保证不等于真实车辆许可&quot;">​</a></h3><p>无遗憾学习分析依赖有限时域、标签质量和分布假设。传感器失效、动力学误差和安全接管仍需独立验证。</p><p><img src="'+o+'" alt="DAgger 通过学习策略访问状态并由专家重标记"></p><h2 id="二、dagger-为什么要让学习策略先走" tabindex="-1">二、DAgger 为什么要让学习策略先走 <a class="header-anchor" href="#二、dagger-为什么要让学习策略先走" aria-label="Permalink to &quot;二、DAgger 为什么要让学习策略先走&quot;">​</a></h2><h3 id="_2-1-专家数据覆盖不了策略错误状态" tabindex="-1">2.1 专家数据覆盖不了策略错误状态 <a class="header-anchor" href="#_2-1-专家数据覆盖不了策略错误状态" aria-label="Permalink to &quot;2.1 专家数据覆盖不了策略错误状态&quot;">​</a></h3><p>专家几乎不会把车开到道路边缘、急转过度或错过路口的位置，纯 BC 数据自然没有这些状态。</p><h3 id="_2-2-学习策略会改变后续状态" tabindex="-1">2.2 学习策略会改变后续状态 <a class="header-anchor" href="#_2-2-学习策略会改变后续状态" aria-label="Permalink to &quot;2.2 学习策略会改变后续状态&quot;">​</a></h3><p>动作误差不仅影响当前控制，还影响下一观测。DAgger 直接采集由学习策略诱导的状态，解决协变量偏移的来源。</p><h3 id="_2-3-专家标签提供恢复动作" tabindex="-1">2.3 专家标签提供恢复动作 <a class="header-anchor" href="#_2-3-专家标签提供恢复动作" aria-label="Permalink to &quot;2.3 专家标签提供恢复动作&quot;">​</a></h3><p>专家在偏离状态上给出的动作告诉策略怎样回到可行轨迹，而不是只告诉它理想状态下应该怎么做。</p><h3 id="_2-4-聚合数据逐步扩大覆盖" tabindex="-1">2.4 聚合数据逐步扩大覆盖 <a class="header-anchor" href="#_2-4-聚合数据逐步扩大覆盖" aria-label="Permalink to &quot;2.4 聚合数据逐步扩大覆盖&quot;">​</a></h3><p>每轮新增状态—专家动作对，旧数据保留用于防止遗忘。数据集从专家分布逐步扩展到学习策略分布。</p><p><img src="'+l+'" alt="DAgger 让数据覆盖从专家分布扩展到学习策略诱导状态"></p><h2 id="三、dagger-的迭代流程怎样展开" tabindex="-1">三、DAgger 的迭代流程怎样展开 <a class="header-anchor" href="#三、dagger-的迭代流程怎样展开" aria-label="Permalink to &quot;三、DAgger 的迭代流程怎样展开&quot;">​</a></h2><h3 id="_3-1-用初始专家数据训练策略" tabindex="-1">3.1 用初始专家数据训练策略 <a class="header-anchor" href="#_3-1-用初始专家数据训练策略" aria-label="Permalink to &quot;3.1 用初始专家数据训练策略&quot;">​</a></h3><p>先使用 BC 得到 (\\hat\\pi_1)，保证策略具备基本行为。</p><h3 id="_3-2-用混合策略采集状态" tabindex="-1">3.2 用混合策略采集状态 <a class="header-anchor" href="#_3-2-用混合策略采集状态" aria-label="Permalink to &quot;3.2 用混合策略采集状态&quot;">​</a></h3><p>在第 (i) 轮以概率 (\\beta_i) 使用专家动作，以 (1-\\beta_i) 使用学习策略动作，执行完整轨迹并记录访问状态。</p><h3 id="_3-3-专家为访问状态提供标签" tabindex="-1">3.3 专家为访问状态提供标签 <a class="header-anchor" href="#_3-3-专家为访问状态提供标签" aria-label="Permalink to &quot;3.3 专家为访问状态提供标签&quot;">​</a></h3><p>对每个访问状态查询专家动作、目标轨迹或代价。专家标签应与学习策略实际观测和延迟一致。</p><h3 id="_3-4-聚合数据并重新训练" tabindex="-1">3.4 聚合数据并重新训练 <a class="header-anchor" href="#_3-4-聚合数据并重新训练" aria-label="Permalink to &quot;3.4 聚合数据并重新训练&quot;">​</a></h3><p>把新标签加入 (D)，在聚合数据上训练 (\\hat\\pi_{i+1})。新策略再产生下一轮访问分布。</p><p><img src="'+h+'" alt="DAgger 的混合采集、专家标注与数据聚合循环"></p><h2 id="四、混合比例为什么不能随意退火" tabindex="-1">四、混合比例为什么不能随意退火 <a class="header-anchor" href="#四、混合比例为什么不能随意退火" aria-label="Permalink to &quot;四、混合比例为什么不能随意退火&quot;">​</a></h2><h3 id="_4-1-专家比例太高会覆盖不到错误状态" tabindex="-1">4.1 专家比例太高会覆盖不到错误状态 <a class="header-anchor" href="#_4-1-专家比例太高会覆盖不到错误状态" aria-label="Permalink to &quot;4.1 专家比例太高会覆盖不到错误状态&quot;">​</a></h3><p>如果专家几乎每一步都接管，学习策略很少真正走出专家分布，DAgger 退化成普通示范采集。</p><h3 id="_4-2-专家比例下降太快会造成风险" tabindex="-1">4.2 专家比例下降太快会造成风险 <a class="header-anchor" href="#_4-2-专家比例下降太快会造成风险" aria-label="Permalink to &quot;4.2 专家比例下降太快会造成风险&quot;">​</a></h3><p>策略尚未学会恢复就被迫独立执行，可能触发碰撞、越界和不可逆故障。</p><h3 id="_4-3-退火应依据能力和风险" tabindex="-1">4.3 退火应依据能力和风险 <a class="header-anchor" href="#_4-3-退火应依据能力和风险" aria-label="Permalink to &quot;4.3 退火应依据能力和风险&quot;">​</a></h3><p>成功率、恢复时间、接管原因和安全约束违例比固定轮数更适合作为退火参考。</p><h3 id="_4-4-评估阶段必须关闭专家接管" tabindex="-1">4.4 评估阶段必须关闭专家接管 <a class="header-anchor" href="#_4-4-评估阶段必须关闭专家接管" aria-label="Permalink to &quot;4.4 评估阶段必须关闭专家接管&quot;">​</a></h3><p>如果专家仍在运行时修正动作，测到的是混合系统性能，不是学习策略性能。可分别报告接管后性能，但不能混淆。</p><h2 id="五、dagger-的标签如何设计" tabindex="-1">五、DAgger 的标签如何设计 <a class="header-anchor" href="#五、dagger-的标签如何设计" aria-label="Permalink to &quot;五、DAgger 的标签如何设计&quot;">​</a></h2><h3 id="_5-1-标签可以是动作也可以是代价" tabindex="-1">5.1 标签可以是动作也可以是代价 <a class="header-anchor" href="#_5-1-标签可以是动作也可以是代价" aria-label="Permalink to &quot;5.1 标签可以是动作也可以是代价&quot;">​</a></h3><p>连续控制可让专家给目标动作，规划场景可给候选动作代价或排序。标签形式应匹配策略输出。</p><h3 id="_5-2-标签需要记录专家上下文" tabindex="-1">5.2 标签需要记录专家上下文 <a class="header-anchor" href="#_5-2-标签需要记录专家上下文" aria-label="Permalink to &quot;5.2 标签需要记录专家上下文&quot;">​</a></h3><p>专家动作背后的目标车道、期望速度、风险等级和时间戳有助于处理多模态决策。</p><h3 id="_5-3-多专家标签需要聚合规则" tabindex="-1">5.3 多专家标签需要聚合规则 <a class="header-anchor" href="#_5-3-多专家标签需要聚合规则" aria-label="Permalink to &quot;5.3 多专家标签需要聚合规则&quot;">​</a></h3><p>平均不同风格动作可能产生不可执行的中间动作。可以按场景、风格或安全优先级分组训练。</p><h3 id="_5-4-专家标签也可能错误" tabindex="-1">5.4 专家标签也可能错误 <a class="header-anchor" href="#_5-4-专家标签也可能错误" aria-label="Permalink to &quot;5.4 专家标签也可能错误&quot;">​</a></h3><p>DAgger 不会自动过滤专家噪声。应保留置信度、冲突检测和安全审查机制。</p><p><img src="'+n+'" alt="专家标签的动作、目标与安全上下文"></p><h2 id="六、自动驾驶中怎样安全运行-dagger" tabindex="-1">六、自动驾驶中怎样安全运行 DAgger <a class="header-anchor" href="#六、自动驾驶中怎样安全运行-dagger" aria-label="Permalink to &quot;六、自动驾驶中怎样安全运行 DAgger&quot;">​</a></h2><h3 id="_6-1-优先在仿真和影子模式采集" tabindex="-1">6.1 优先在仿真和影子模式采集 <a class="header-anchor" href="#_6-1-优先在仿真和影子模式采集" aria-label="Permalink to &quot;6.1 优先在仿真和影子模式采集&quot;">​</a></h3><p>学习策略只提出动作，专家或现有控制器负责执行，先收集策略诱导状态而不让其直接控制真实车辆。</p><h3 id="_6-2-接管规则必须可解释" tabindex="-1">6.2 接管规则必须可解释 <a class="header-anchor" href="#_6-2-接管规则必须可解释" aria-label="Permalink to &quot;6.2 接管规则必须可解释&quot;">​</a></h3><p>明确何时因车道偏差、碰撞风险、控制饱和或感知异常切换到专家或备用控制器。</p><h3 id="_6-3-记录提议动作与实际动作" tabindex="-1">6.3 记录提议动作与实际动作 <a class="header-anchor" href="#_6-3-记录提议动作与实际动作" aria-label="Permalink to &quot;6.3 记录提议动作与实际动作&quot;">​</a></h3><p>安全层修改动作后，数据集应同时保存学习策略提议、专家标签、最终执行动作和介入原因。</p><p><img src="'+s+'" alt="DAgger 在自动驾驶中的影子策略与安全接管链"></p><h2 id="七、一个最小实验怎样设计" tabindex="-1">七、一个最小实验怎样设计 <a class="header-anchor" href="#七、一个最小实验怎样设计" aria-label="Permalink to &quot;七、一个最小实验怎样设计&quot;">​</a></h2><h3 id="_7-1-从简化车道保持开始" tabindex="-1">7.1 从简化车道保持开始 <a class="header-anchor" href="#_7-1-从简化车道保持开始" aria-label="Permalink to &quot;7.1 从简化车道保持开始&quot;">​</a></h3><p>用经典控制器作为专家，让 BC 策略先在正常状态训练，再允许其施加小扰动。</p><h3 id="_7-2-比较-bc-与-dagger" tabindex="-1">7.2 比较 BC 与 DAgger <a class="header-anchor" href="#_7-2-比较-bc-与-dagger" aria-label="Permalink to &quot;7.2 比较 BC 与 DAgger&quot;">​</a></h3><p>统一初始数据、环境步和网络，比较闭环偏差、恢复成功、接管率和专家查询次数。</p><h3 id="_7-3-逐步扩展扰动范围" tabindex="-1">7.3 逐步扩展扰动范围 <a class="header-anchor" href="#_7-3-逐步扩展扰动范围" aria-label="Permalink to &quot;7.3 逐步扩展扰动范围&quot;">​</a></h3><p>从小横向偏差扩展到延迟、曲率变化和传感器噪声，观察数据覆盖与安全指标。</p><h3 id="_7-4-做标签延迟消融" tabindex="-1">7.4 做标签延迟消融 <a class="header-anchor" href="#_7-4-做标签延迟消融" aria-label="Permalink to &quot;7.4 做标签延迟消融&quot;">​</a></h3><p>模拟专家查询延迟、旧标签和动作执行延迟，检查策略是否学习到过时的恢复动作。</p><h2 id="八、最常见的实现错误" tabindex="-1">八、最常见的实现错误 <a class="header-anchor" href="#八、最常见的实现错误" aria-label="Permalink to &quot;八、最常见的实现错误&quot;">​</a></h2><h3 id="_8-1-只聚合专家正常轨迹" tabindex="-1">8.1 只聚合专家正常轨迹 <a class="header-anchor" href="#_8-1-只聚合专家正常轨迹" aria-label="Permalink to &quot;8.1 只聚合专家正常轨迹&quot;">​</a></h3><p>这样没有采集学习策略真实访问的偏离状态，核心问题仍然存在。</p><h3 id="_8-2-混合策略执行但标签时间错位" tabindex="-1">8.2 混合策略执行但标签时间错位 <a class="header-anchor" href="#_8-2-混合策略执行但标签时间错位" aria-label="Permalink to &quot;8.2 混合策略执行但标签时间错位&quot;">​</a></h3><p>专家看到的是时刻 (t) 观测，记录的却是 (t+1) 动作，会把控制因果关系打乱。</p><h3 id="_8-3-用接管后轨迹宣称策略安全" tabindex="-1">8.3 用接管后轨迹宣称策略安全 <a class="header-anchor" href="#_8-3-用接管后轨迹宣称策略安全" aria-label="Permalink to &quot;8.3 用接管后轨迹宣称策略安全&quot;">​</a></h3><p>接管已经改变了执行结果。必须分别报告原策略提议、接管前风险和接管后系统表现。</p><h3 id="_8-4-数据集无限增长却没有采样策略" tabindex="-1">8.4 数据集无限增长却没有采样策略 <a class="header-anchor" href="#_8-4-数据集无限增长却没有采样策略" aria-label="Permalink to &quot;8.4 数据集无限增长却没有采样策略&quot;">​</a></h3><p>应按场景、风险和新颖性管理聚合数据，否则旧正常数据会淹没关键恢复样本。</p><h2 id="九、学到什么程度才算掌握" tabindex="-1">九、学到什么程度才算掌握 <a class="header-anchor" href="#九、学到什么程度才算掌握" aria-label="Permalink to &quot;九、学到什么程度才算掌握&quot;">​</a></h2><h3 id="_9-1-能解释-dagger-与-bc-的数据分布差异" tabindex="-1">9.1 能解释 DAgger 与 BC 的数据分布差异 <a class="header-anchor" href="#_9-1-能解释-dagger-与-bc-的数据分布差异" aria-label="Permalink to &quot;9.1 能解释 DAgger 与 BC 的数据分布差异&quot;">​</a></h3><p>你应能指出专家数据来自 (d_{\\pi_E})，DAgger 逐步加入 (d_{\\pi_i}) 诱导状态。</p><h3 id="_9-2-能设计混合比例与回退条件" tabindex="-1">9.2 能设计混合比例与回退条件 <a class="header-anchor" href="#_9-2-能设计混合比例与回退条件" aria-label="Permalink to &quot;9.2 能设计混合比例与回退条件&quot;">​</a></h3><p>你应能根据安全和恢复指标调度专家接管，而不是固定轮数盲目退火。</p><h3 id="_9-3-能审计提议动作与执行动作" tabindex="-1">9.3 能审计提议动作与执行动作 <a class="header-anchor" href="#_9-3-能审计提议动作与执行动作" aria-label="Permalink to &quot;9.3 能审计提议动作与执行动作&quot;">​</a></h3><p>你应能在日志中还原学习策略提出了什么、专家建议了什么、最后执行了什么。</p><h3 id="_9-4-能进入逆强化学习" tabindex="-1">9.4 能进入逆强化学习 <a class="header-anchor" href="#_9-4-能进入逆强化学习" aria-label="Permalink to &quot;9.4 能进入逆强化学习&quot;">​</a></h3><p>下一篇将不再直接复制专家动作，而是尝试从专家轨迹反推其隐含目标。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p><a href="https://arxiv.org/abs/1011.0686" target="_blank" rel="noreferrer">Ross、Gordon 与 Bagnell《A Reduction of Imitation Learning and Structured Prediction to No-Regret Online Learning》</a></p><p><a href="https://proceedings.mlr.press/v15/ross11a/ross11a.pdf" target="_blank" rel="noreferrer">DAgger 论文 PDF</a></p><p><a href="https://raw.githubusercontent.com/datawhalechina/easy-rl/master/docs/chapter11/chapter11.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第十一章模仿学习</a></p>',91)])])}const f=e(g,[["render",d]]);export{m as __pageData,f as default};
